window.LoadCorrections={
 t:UnifiedOutbound.t,
 async mount(id,d){const {items:records}=await API.request('/outbound-workspace/orders/'+id+'/corrections');const t=this.t,active=records.find(x=>['REQUESTED','AUTHORIZED','RETURN_VERIFIED'].includes(x.status)),ended=['CANCELLED','REVERSED'].includes(d.status),types=d.workflow_state==='OUTBOUND'?['VEHICLE','RETURN_OUTBOUND']:['PENDING','READY','REJECTED','DEPARTED_PENDING','DEPARTED_CORRECTION'].includes(d.workflow_state)?['VEHICLE','CANCEL_LOAD']:[],section=document.createElement('section');section.id='ux11-load-corrections';section.className='ux11-corrections panel';section.innerHTML='<h2>'+t('更正与处理记录','Corrections and Resolution')+'</h2>'+(active?'<p class="dialog-notice">'+t('本单已有处理中更正，请先完成该申请。','This order already has an open correction. Complete it first.')+'</p>':'')+(!ended&&!active&&types.length&&Business.can('load:write')?'<button class="button secondary" id="ux11-correction-new">'+t('申请本单更正','Request Correction')+'</button>':'')+'<div id="ux11-correction-records">'+records.map(c=>'<details data-correction-record="'+c.id+'"><summary><span data-no-i18n>'+esc(c.code)+'</span> · '+I18n.translate(V27Reliability.kind(c.kind),true)+' · '+this.status(c)+'</summary><div data-correction-body="'+c.id+'"></div></details>').join('')+'</div>';$('page-content').append(section);const cancel=$('v32-cancel');if(cancel)section.prepend(cancel.closest('details')||cancel);if($('ux11-correction-new'))$('ux11-correction-new').onclick=()=>this.create(d,types);for(const el of section.querySelectorAll('[data-correction-record]'))el.ontoggle=()=>{if(el.open&&!el.dataset.loaded)this.show(el.dataset.correctionRecord).then(()=>el.dataset.loaded='1').catch(e=>notify(e.message));};const selected=new URLSearchParams(location.search).get('correction');if(selected){const el=section.querySelector('[data-correction-record="'+CSS.escape(selected)+'"]');if(el){el.dataset.loaded='1';el.open=true;await this.show(selected);}} },
 async create(load,types){const t=this.t,m=await Business.load();dialog(t('申请本单更正','Request Correction'),`<form id="ux11-correction-create" class="user-form"><p data-no-i18n>${esc(load.loading_plan?.packing_list_no||load.code)} · ${esc(load.vehicle_no)}</p><label>${t('处理类型','Correction Type')}<select name="kind">${types.map(k=>'<option value="'+k+'">'+I18n.translate(V27Reliability.kind(k),true)+'</option>').join('')}</select></label><label data-vehicle>${t('更正后车牌','Corrected Truck Plate')}<input name="vehicle_no" maxlength="80"></label><div data-return><label>${t('退回临时堆存区','Temporary Return Location')}<select name="return_location_id"><option value="">${t('请选择','Select')}</option>${Business.options(m.locations.filter(l=>l.active&&l.project_id===load.project_id&&l.map_usage==='TEMPORARY'),null,'code')}</select></label><label class="check-label"><input name="physical_return_verified" type="checkbox">${t('已核查实物退回，仍须复核','Physical Return Checked; Verification Required')}</label><label>${t('实物核查依据','Physical Evidence')}<textarea name="physical_evidence" minlength="5" maxlength="1000"></textarea></label></div><label>${t('更正原因及依据','Correction Reason and Evidence')}<textarea name="reason" required minlength="5" maxlength="2000"></textarea></label><p id="ux11-correction-error" class="error" role="alert"></p><button class="button primary">${t('提交更正申请','Submit Correction Request')}</button></form>`);const f=$('ux11-correction-create'),toggle=()=>{const vehicle=f.elements.kind.value==='VEHICLE';f.querySelector('[data-vehicle]').hidden=!vehicle;f.querySelector('[data-return]').hidden=vehicle;f.elements.vehicle_no.required=vehicle;for(const k of ['return_location_id','physical_return_verified','physical_evidence'])f.elements[k].required=!vehicle;};f.elements.kind.onchange=toggle;toggle();f.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(f)),details=b.kind==='VEHICLE'?{vehicle_no:b.vehicle_no}:{return_location_id:b.return_location_id,physical_return_verified:b.physical_return_verified==='on',physical_evidence:b.physical_evidence};const result=await API.request('/v27/corrections',{method:'POST',body:{loading_id:load.id,version:load.version,kind:b.kind,reason:b.reason,details}});$('dialog').close();ProductContext.dirty=false;await Router.go('/outbounds/loads/'+load.id+'?correction='+result.id);}catch(err){$('ux11-correction-error').textContent=err.message;e.submitter.disabled=false;}};},
 status(c){
  if(c.kind==='RETURN_OUTBOUND'){
   const stage={AUTHORIZED:['已授权 · 待实物核验','Authorized · Awaiting Physical Verification'],
    RETURN_VERIFIED:['已核验 · 待执行冲销','Verified · Awaiting Reversal'],APPLIED:['已冲销','Reversed']};
   if(stage[c.status])return this.t(...stage[c.status]);
  }
  return I18n.translate(V27Reliability.status(c.status),true);
 },
 recoveryMessage(blocker){
  const messages={ORIGINAL_PREPARATION_UNAVAILABLE:['原备货单状态或来源记录无法核对。','The original preparation could not be verified.'],
   SALES_PLAN_UNAVAILABLE:['请核对原销售计划是否可继续办理。','Check whether the original sales plan is open.'],
   RETURNED_STOCK_CHANGED:['返厂捆包已有后续流转或库存状态变化。','Returned bundles have subsequent movement or inventory changes.'],
   OTHER_LOADING:['原批次还有其他有效装车业务。','The original lot has another active loading operation.'],
   ORIGINAL_BATCH_PARTIAL:['原批次有未核实去向的捆包，须先核对。','Some bundles in the original lot require verification.'],
   LOCATION_CONFLICT:['原备货货位不可用或已被其他货物占用。','The original preparation location is unavailable or occupied.'],
   RETURN_EVIDENCE_MISSING:['缺少本次冲销的库存退回凭证，请核对冲销记录。','The stock return record is missing. Check the reversal history.'],
   STOCK_NOT_ON_SITE:['捆包当前不在库，请核对实物及库存状态。','The bundle is out of stock. Check its physical location and stock status.'],
   RETURN_LOCATION_CHANGED:['捆包当前货位与冲销登记不符，请核对移库记录。','The bundle is away from its recorded return location. Check its transfer history.'],
   ACTIVE_RESERVATION:['捆包已有有效库存占用，请核对当前占用。','The bundle has an active reservation. Check its current allocation.'],
   ACTIVE_LOADING:['捆包已分配给其他装车作业，请核对装车记录。','The bundle is assigned to an active loading operation. Check its loading record.'],
   STOCK_ADJUSTMENT_PENDING:['捆包有待处理的库存调整，请先办理。','The bundle has a pending stock adjustment. Resolve it first.'],
   SUBSEQUENT_STOCK_ACTIVITY:['冲销后已有库存流转，请核对后续库存记录。','Stock movements were recorded after the reversal. Check the movement history.'],
   BUNDLE_DATA_CHANGED:['捆包资料或重量与退回记录不一致，请核对捆包档案。','The bundle details or weight differ from the return record. Check its inventory record.']};
  return this.t(...(messages[blocker]||['请核对返厂捆包和原备货单后再试。','Verify the returned bundles and original preparation, then try again.']));
 },
 blockedRecovery(recovery){
  const t=this.t,items=(recovery.stock_blockers||[]).filter(item=>item?.bundle_no&&item.reason);
  const detailed=recovery.return_area_unavailable||items.length>0;
  const summary=t('出库已冲销，暂不能恢复原备货单。','Stock issue was reversed. The original preparation cannot be restored yet.');
  const reason=recovery.blocker==='RETURNED_STOCK_CHANGED'&&detailed?'':' '+this.recoveryMessage(recovery.blocker);
  const area=recovery.return_area_unavailable?'<p data-return-area-unavailable>'+esc(t('登记的退回临时堆存区不可用，请核对货位及仓库是否启用。',
   'The recorded temporary return location is unavailable. Check whether the location and warehouse are active.'))+'</p>':'';
  const stock=items.length?'<details data-return-stock-blockers open><summary>'+esc(t('需核对的原单捆包','Original Bundles to Check'))+
   '</summary><ul>'+items.map(item=>'<li><strong data-no-i18n>'+esc(item.bundle_no)+'</strong> · '+
    esc(this.recoveryMessage(item.reason))+'</li>').join('')+'</ul></details>':'';
  return '<p class="dialog-notice" data-return-preparation-notice tabindex="-1">'+esc(summary+reason)+'</p>'+area+stock;
 },
 async show(id,correction){
  const c=correction||await API.request('/v27/corrections/'+id),root=document.querySelector('[data-correction-body="'+CSS.escape(id)+'"]');
  if(!root)return;
  const t=this.t,actions=[],recovery=c.preparation_recovery;
  if(Business.can('outbound:approve')){
   if(c.status==='REQUESTED')actions.push(['authorize','授权更正','Authorize']);
   if(c.status==='RETURN_VERIFIED'||c.status==='AUTHORIZED'&&c.kind==='VEHICLE')
    actions.push(c.kind==='RETURN_OUTBOUND'?['apply','执行返厂冲销','Apply Return Reversal']:['apply','执行授权更正','Apply Correction']);
   if(['REQUESTED','AUTHORIZED','RETURN_VERIFIED'].includes(c.status))actions.push(['reject','驳回更正','Reject']);
   if(recovery?.state==='READY')actions.push(['restore-preparation','恢复备货单','Restore Preparation']);
  }
  if(Business.can('load:review')&&(CurrentUser.role_code==='admin'||c.requested_by!==CurrentUser.id)&&c.status==='AUTHORIZED'&&c.kind!=='VEHICLE')
   actions.push(['verify-return','核验实物退回','Verify Physical Return']);
  let notice='';
  if(recovery?.state==='RESTORED')notice='<p class="dialog-notice">'+t('已恢复原备货单。','The original preparation was restored.')+' '+
   (Business.can('allocation:read')?recovery.allocation_ids.map(id=>'<a href="/preparation/'+esc(id)+'">'+
    t('查看备货单','View Preparation')+'</a>').join(' · '):'')+'</p>';
  if(recovery?.state==='READY')notice='<p class="dialog-notice">'+t('出库已冲销，原备货单待恢复。','Stock issue was reversed. The original preparation awaits restoration.')+'</p>';
  if(recovery?.state==='BLOCKED')notice=this.blockedRecovery(recovery);
  root.innerHTML='<p data-no-i18n>'+esc(c.reason)+'</p>'+notice+'<div class="business-toolbar">'+actions.map(([a,z,e])=>
   '<button type="button" class="button secondary" data-ux11-correction-action="'+a+'">'+t(z,e)+'</button>').join('')+'</div>'+
   '<h3>'+t('审批与执行历史','Review and Execution History')+'</h3>'+c.steps.map(s=>'<p data-no-i18n>'+
    esc(BusinessTime.display(s.occurred_at)+' · '+s.actor_name+' · '+s.action+' · '+s.reason)+'</p>').join('')+
   '<details><summary>'+t('原单据及更正依据','Original Record and Evidence')+'</summary><pre data-no-i18n>'+
    esc(JSON.stringify({original:c.original_snapshot,proposed:c.proposed_data,bundles:c.bundle_snapshot},null,2))+'</pre></details>';
  for(const b of root.querySelectorAll('[data-ux11-correction-action]'))b.onclick=()=>V27Counts.reasonForm(b.textContent,async reason=>{
   const result=await API.request('/v27/corrections/'+id+'/'+b.dataset.ux11CorrectionAction,{method:'POST',body:{version:c.version,reason}});
   if(result.state==='BLOCKED'){
    await this.show(id,{...c,preparation_recovery:result});
    requestAnimationFrame(()=>root.querySelector('[data-return-preparation-notice]')?.focus());
    return;
   }
   ProductContext.dirty=false;
   await Router.go('/outbounds/loads/'+c.loading_id+'?correction='+c.id);
  });
 }
};
