OutboundCenter.tabs=()=>UnifiedOutbound.toolbar(true);
const ux11Load=Flow.load.bind(Flow);Flow.load=async function(id){const d=await ux11Load(id);await LoadCorrections.mount(id,d);return d;};
const ux11CoDetail=CobaltExecutionUI.detail.bind(CobaltExecutionUI);CobaltExecutionUI.detail=async function(id){await ux11CoDetail(id);const t=UnifiedOutbound.t,d=this.data,section=document.createElement('section');section.id='ux11-co-corrections';section.className='ux11-corrections panel';section.innerHTML='<h2>'+t('更正与异常处理','Corrections and Exceptions')+'</h2>';const ex=$('co-execution-exceptions');if(ex)section.append(ex);const form=$('co-execution-departure');if(form&&d.execution?.state!=='LOADED'){const h=form.previousElementSibling;if(h?.tagName==='H3')section.append(h);section.append(form);}if(!d.execution&&UnifiedOutbound.can('loading-plan:read'))section.insertAdjacentHTML('beforeend','<a class="button secondary" href="/loading-plans/orders/'+d.order.plan_id+'">'+t('申请车辆调整 / 解除匹配','Request Vehicle Change / Unmatch')+'</a>');$('page-content').append(section);const w=await API.request('/cobalt/outbound-workspace/orders/'+id+'/weight');document.querySelector('.co-execution-page h2')?.insertAdjacentHTML('afterend',InventoryControl.warning(w).replace(' 捆 ·',' 袋 ·'));};
ShippingOverview.outbounds=()=>UnifiedOutbound.list();CobaltExecutionUI.list=()=>UnifiedOutbound.list();
const ux11CoRoute=CobaltUI.route.bind(CobaltUI);CobaltUI.route=p=>p==='/outbounds/templates'?UnifiedOutbound.templates():p==='/outbounds/weight-settings'?UnifiedOutbound.weightSettings():ux11CoRoute(p);
const ux11CoLanguage=CobaltUI.languageChanged.bind(CobaltUI);CobaltUI.languageChanged=()=>['/outbounds/templates','/outbounds/weight-settings'].includes(location.pathname)?UnifiedOutbound.language():ux11CoLanguage();
const ux11CoPage=ProductContext.cobaltPage.bind(ProductContext);ProductContext.cobaltPage=p=>!ProductContext.isCopper()&&['/outbounds/templates','/outbounds/weight-settings'].includes(p)||ux11CoPage(p);
ProductPolish.nav=()=>UnifiedNavigation.refresh();
const ux11Permission=Router.permission.bind(Router);Router.permission=p=>p==='/outbounds'?'load:read':ux11Permission(p);
const ux11Show=Router.performShow.bind(Router);Router.performShow=async function(...args){const path=location.pathname,q=new URLSearchParams(location.search),handled=path==='/outbounds'&&!['departures','printers'].includes(q.get('view'))||['/outbounds/templates','/outbounds/weight-settings','/outbounds/corrections'].includes(path)||/^\/outbounds\/corrections\/[0-9a-f-]{36}$/.test(path);if(!handled){const r=await ux11Show(...args);UnifiedNavigation.refresh();return r;}this.current=path;this.rendering=true;try{const permission=this.permission(path);if(permission&&!CurrentUser.permissions.includes(permission))throw Error(UnifiedOutbound.t('当前账号没有此页面权限','This account has no permission for this page'));if(path==='/outbounds/templates')await UnifiedOutbound.templates();else if(path==='/outbounds/weight-settings')await UnifiedOutbound.weightSettings();else if(path.startsWith('/outbounds/corrections/')){const c=await API.request('/v27/corrections/'+path.split('/').pop());history.replaceState({},'','/outbounds/loads/'+c.loading_id+'?correction='+c.id);await Flow.load(c.loading_id);}else {if(path==='/outbounds/corrections')history.replaceState({},'','/outbounds');await UnifiedOutbound.list();}I18n.apply();BusinessWorkflow.mount();UnifiedNavigation.refresh();}catch(e){this.page(UnifiedOutbound.t('页面暂不可用','Page Unavailable'),'<p class="error" role="alert">'+esc(e.message)+'</p>');}finally{this.rendering=false;AdaptiveLayout.queue();}};
const ux11Init=Router.init.bind(Router);Router.init=async function(...args){const r=await ux11Init(...args);UnifiedNavigation.refresh();if(location.pathname==='/overview'&&!CurrentUser.permissions.includes('dashboard:read')&&CurrentUser.permissions.includes('plan:read'))await this.go('/sales-plans',true);return r;};
const ux11Mount=ProductContext.mount.bind(ProductContext);ProductContext.mount=function(){ux11Mount();const set=I18n.set.bind(I18n);I18n.set=language=>{const r=set(language);UnifiedNavigation.refresh();return r;};UnifiedNavigation.refresh();};
